# Immutable archive aggregation and deterministic algebra fixtures only. No model fits.
stopifnot(as.character(getRversion())=='4.5.2')
a<-grep('^--file=',commandArgs(),value=TRUE)[1];C<-dirname(dirname(normalizePath(sub('^--file=','',a))));R<-dirname(dirname(C));P<-dirname(R)
archive<-Sys.getenv('TSR_TIER1_ARCHIVE')
sha<-function(p)strsplit(system2('shasum',c('-a','256',shQuote(p)),stdout=TRUE),'[[:space:]]+')[[1]][1]
inv<-read.csv(file.path(C,'evidence/source_inventory.csv'));for(i in seq_len(nrow(inv)))stopifnot(sha(if(nzchar(inv$project_relative[i]))file.path(P,inv$project_relative[i]) else archive)==inv$sha256[i])
bind<-function(x)if(length(x))do.call(rbind,x) else data.frame()
wr<-function(x,n,w='tables')write.csv(x,file.path(C,w,n),row.names=FALSE,na='NA')
interval<-function(v,binary=FALSE){v<-v[is.finite(v)];n<-length(v);if(!n)return(c(n_finite=0,events=NA,mean=NA,mcse=NA,lower=NA,upper=NA));se<-sd(v)/sqrt(n);ci<-mean(v)+c(-1,1)*qt(.975,n-1)*se;if(binary){stopifnot(all(v%in%0:1));ci<-binom.test(sum(v),n)$conf.int};c(n_finite=n,events=if(binary)sum(v) else NA,mean=mean(v),mcse=se,lower=ci[1],upper=ci[2])}
pairci<-function(a,b,binary=FALSE){ok<-is.finite(a)&is.finite(b);a<-a[ok];b<-b[ok];n<-length(a);z<-interval(a-b);up<-down<-NA;if(binary&&n){up<-sum(a==1&b==0);down<-sum(a==0&b==1);u<-binom.test(up,n,conf.level=.975)$conf.int;d<-binom.test(down,n,conf.level=.975)$conf.int;z[c('lower','upper')]<-c(u[1]-d[2],u[2]-d[1])};c(z,n_up=up,n_down=down)}
main<-function(){
 t<-tempfile('r2c3_archive_');dir.create(t);on.exit(unlink(t,recursive=TRUE));untar(archive,files='replications.csv',exdir=t);all<-read.csv(file.path(t,'replications.csv'))
 design<-read.csv(file.path(P,'revision_scientific_reports/config/design.csv'));design<-design[design$tier==1,];tasks<-read.csv(file.path(P,'revision_scientific_reports/config/tasks_tier1.csv'))
 stopifnot(nrow(all)==98800,all(all$status=='OK'),length(unique(all$cell_id))==282,nrow(tasks)==9880,!anyDuplicated(all[c('cell_id','replication')]))
 keys<-paste(all$cell_id,all$replication);tk<-unlist(lapply(seq_len(nrow(tasks)),function(i)paste(tasks$cell_id[i],seq.int(tasks$rep_start[i],tasks$rep_end[i]))));stopifnot(!anyDuplicated(tk),setequal(keys,tk))
 idx<-match(all$cell_id,design$cell_id);for(nm in intersect(names(all),names(design)))stopifnot(identical(is.na(all[[nm]]),is.na(design[[nm]][idx])),all(as.character(all[[nm]])==as.character(design[[nm]][idx]),na.rm=TRUE))
 env<-new.env();sys.source(file.path(P,'revision_scientific_reports/R/common.R'),env)
 for(s in c('data','algorithm','null')){stream<-match(s,c('data','algorithm','null'))-1L;rep<-if(s=='data')rep(1L,nrow(all)) else all[[paste0(s,'_repeat')]];stopifnot(all(all[[paste0(s,'_seed')]]==mapply(env$seed_id,all$dataset_id,all$replication,rep,MoreArgs=list(stream=stream))))}
 x<-all[all$method=='TSRClust',];z<-x[x$experiment=='B'|(x$experiment=='C'&x$density==2&x$minpts_multiplier==2&x$B==49),];stopifnot(nrow(z)==22000,length(unique(z$cell_id))==110,setequal(unique(z$novelty),c(.95,.975,.99,.995,.999)))
 z$entered_mc<-as.integer(z$rejection_reason%in%c('accepted','global_p','candidate_max'));stopifnot(all(z$any_native_micro==as.integer(z$n_accepted_micro>0)))
 metrics<-c('MajorARI','MinorityClusterF1','MinorityDetectionF1_all_extra_v2','AnyMicroDiscovery','any_native_micro','SpuriousExtraClusters','MacroFalsePositiveReassignment','end_to_end_seconds','micro_seconds','n_accepted_micro','residual_assignment_rate','global_p','entered_mc');binary<-c('AnyMicroDiscovery','any_native_micro','entered_mc')
 meta<-c('cell_id','experiment','scenario','reference','novelty','p','q','minority_ratio','minority_proximity','noise_type','rule','n','requested_alpha','dataset_id')
 cells<-reasons<-list();for(cid in unique(z$cell_id)){a<-z[z$cell_id==cid,];m<-a[1,meta];rownames(m)<-NULL;for(v in metrics)cells[[length(cells)+1]]<-cbind(m,n_records=nrow(a),metric=v,as.data.frame(as.list(interval(a[[v]],v%in%binary))));for(reason in unique(a$rejection_reason))reasons[[length(reasons)+1]]<-cbind(m,reason=reason,count=sum(a$rejection_reason==reason),n_records=nrow(a))}
 cells<-bind(cells);wr(cells,'cell_summaries.csv');wr(bind(reasons),'rejection_reasons.csv')
 fields<-c('n','p','main_k','separation','main_structure','main_distribution','main_weights','residual_total','minority_ratio','q','minority_shape','minority_sd','minority_proximity','noise_type','mode','nR','data_seed','algorithm_seed','null_seed','algorithm_repeat','null_repeat','algorithm_version','metric_version','reference','novelty','density','minpts_multiplier','B','nstart','regime','kmax','structure_alpha','restr_fact','eps_grid_size','requested_alpha','rule')
 proof<-changes<-list();counter<-0L
 compare<-function(a,b,vary){a<-a[order(a$replication),];b<-b[order(b$replication),];stopifnot(nrow(a)==nrow(b),identical(a$replication,b$replication),identical(a$dataset_id,b$dataset_id));stopifnot(all(vapply(setdiff(fields,vary),function(v)identical(a[[v]],b[[v]]),logical(1))));stopifnot(identical(a$n_residual,b$n_residual),identical(a$macro_objective,b$macro_objective),identical(a$macro_code,b$macro_code),identical(a$estimated_K,b$estimated_K));counter<<-counter+1L
 row<-data.frame(contrast_id=counter,family=vary,scenario=a$scenario[1],p=a$p[1],new_cell=a$cell_id[1],baseline_cell=b$cell_id[1],new_reference=a$reference[1],baseline_reference=b$reference[1],new_novelty=a$novelty[1],baseline_novelty=b$novelty[1]);proof[[length(proof)+1]]<<-cbind(row,n_pairs=nrow(a),noncontrast_fields_equal=TRUE,three_starting_seeds_equal=TRUE,macro_objective_code_residual_K_equal=TRUE,raw_X_and_macro_array_hashes_exported=FALSE)
 ch<-cbind(row,n_pairs=nrow(a),entered_mc_up=sum(a$entered_mc==1&b$entered_mc==0),entered_mc_down=sum(a$entered_mc==0&b$entered_mc==1),native_up=sum(a$any_native_micro==1&b$any_native_micro==0),native_down=sum(a$any_native_micro==0&b$any_native_micro==1),F1_changed=sum(abs(a$MinorityClusterF1-b$MinorityClusterF1)>1e-12,na.rm=TRUE),macro_FP_changed=sum(abs(a$MacroFalsePositiveReassignment-b$MacroFalsePositiveReassignment)>1e-12,na.rm=TRUE));changes[[length(changes)+1]]<<-ch
 if(vary=='novelty'&&a$novelty[1]<b$novelty[1])stopifnot(ch$entered_mc_down==0)
 out<-lapply(metrics,function(v)cbind(row,metric=v,mean_new=if(any(is.finite(a[[v]])))mean(a[[v]],na.rm=TRUE) else NA_real_,mean_baseline=if(any(is.finite(b[[v]])))mean(b[[v]],na.rm=TRUE) else NA_real_,as.data.frame(as.list(pairci(a[[v]],b[[v]],v%in%binary)))))
 bind(out)}
 threshold<-refs<-list()
 groups<-unique(z[c('experiment','scenario','reference')]);for(i in seq_len(nrow(groups))){g<-groups[i,];a<-z[z$experiment==g$experiment&z$scenario==g$scenario&z$reference==g$reference,];for(nv in c(.95,.975,.99,.999))threshold[[length(threshold)+1]]<-compare(a[a$novelty==nv,],a[a$novelty==.995,],'novelty')}
 for(sc in unique(z$scenario[z$experiment=='B']))for(nv in sort(unique(z$novelty))){a<-z[z$experiment=='B'&z$scenario==sc&z$novelty==nv,];for(rr in list(c('tclust_direct','legacy_empirical'),c('regularized_mcd','legacy_empirical'),c('regularized_mcd','tclust_direct')))refs[[length(refs)+1]]<-compare(a[a$reference==rr[1],],a[a$reference==rr[2],],'reference')}
 threshold<-bind(threshold);refs<-bind(refs)
 scientific<-c('estimated_K','n_residual','n_accepted_micro','macro_objective','macro_code','any_native_micro','residual_assignment_rate','selected_eps','global_p','rejection_reason',names(z)[match('GlobalARI',names(z)):match('MacroFalsePositiveReassignment',names(z))])
 equaldefault<-list();for(sc in unique(z$scenario[z$experiment=='B'])){a<-z[z$experiment=='B'&z$scenario==sc&z$novelty==.995&z$reference=='tclust_direct',];b<-z[z$experiment=='B'&z$scenario==sc&z$novelty==.995&z$reference=='legacy_empirical',];a<-a[order(a$replication),];b<-b[order(b$replication),];stopifnot(all(vapply(scientific,function(v)identical(a[[v]],b[[v]]),logical(1))));equaldefault[[length(equaldefault)+1]]<-data.frame(scenario=sc,n_pairs=nrow(a),scientific_fields=length(scientific),all_saved_scientific_fields_identical=TRUE)};wr(bind(equaldefault),'default_direct_empirical_identity.csv','evidence')
 wr(threshold,'paired_thresholds.csv');wr(refs,'paired_references.csv');wr(bind(proof),'pairing_proofs.csv','evidence');wr(bind(changes),'decision_changes.csv')
 # Independently reproduce every approved R1C2 five-metric cell and paired row.
 old<-read.csv(file.path(R,'reviewer1/comment2/tables/sensitivity_cell_performance.csv'));for(i in seq_len(nrow(old))){a<-cells[cells$cell_id==old$cell_id[i]&cells$metric==old$metric[i],];stopifnot(nrow(a)==1,a$n_finite==old$n_finite[i]);for(nm in c('mean','mcse','lower','upper')){ov<-old[[switch(nm,lower='lo',upper='hi',nm)]][i];stopifnot(isTRUE(all.equal(a[[nm]],ov,tolerance=1e-11)))}}
 oldp<-read.csv(file.path(R,'reviewer1/comment2/tables/paired_novelty_differences.csv'));for(i in seq_len(nrow(oldp))){a<-threshold[threshold$new_cell==oldp$alternative_cell[i]&threshold$baseline_cell==oldp$baseline_cell[i]&threshold$metric==oldp$metric[i],];stopifnot(nrow(a)==1);for(nm in c('mean','mcse','lower','upper'))stopifnot(isTRUE(all.equal(a[[nm]],oldp[[switch(nm,lower='lo',upper='hi',nm)]][i],tolerance=1e-11)))}
 wr(z[!duplicated(z$cell_id),intersect(names(design),names(z))],'target_design.csv')
 wr(all[!duplicated(all$cell_id),names(design)],'experiment_inventory.csv')
 # Five C positive cells duplicate B isolated empirical at the same novelty: no pooling.
 dup<-list();for(nv in unique(z$novelty)){a<-z[z$experiment=='C'&z$scenario=='positive'&z$novelty==nv,];b<-z[z$experiment=='B'&z$minority_ratio==.05&z$minority_proximity=='isolated'&z$reference=='legacy_empirical'&z$novelty==nv,];a<-a[order(a$replication),];b<-b[order(b$replication),];stopifnot(nrow(a)==200,identical(a$data_seed,b$data_seed));for(v in setdiff(metrics,c('end_to_end_seconds','micro_seconds')))stopifnot(identical(a[[v]],b[[v]]));dup[[length(dup)+1]]<-data.frame(novelty=nv,C_cell=a$cell_id[1],B_cell=b$cell_id[1],n=200,nonruntime_metrics_identical=TRUE)};wr(bind(dup),'duplicate_cells.csv','evidence')
 # Retained objects from historical local pilots: inventory only, not Tier1 substitutes.
 paths<-list.files(file.path(P,'revision_scientific_reports/results'),pattern='^task_.*\\.rds$',recursive=TRUE,full.names=TRUE);walk<-function(a,p='') {if(is.list(a)&&!is.data.frame(a))unlist(lapply(seq_along(a),function(i){nm<-if(!is.null(names(a))&&nzchar(names(a)[i]))names(a)[i] else as.character(i);q<-paste0(p,'/',nm);c(q,walk(a[[i]],q))})) else character()};objects<-lapply(paths,function(p){a<-readRDS(p);ns<-names(a);deep<-walk(a);struc<-capture.output(str(a,max.level=2,list.len=20));data.frame(path=p,bytes=file.info(p)$size,sha256=sha(p),class=paste(class(a),collapse=';'),top_fields=paste(ns,collapse=';'),has_macro_fit_object=any(grepl('/(macro_fit|macro|centers|cov|covariance)$',deep)),nested_fields=paste(unique(gsub('/[0-9]+/','/item/',deep)),collapse=';'),fit_records=length(a$results),structure=paste(struc,collapse=' | '))});wr(bind(objects),'retained_object_inventory.csv','evidence')
 # Deterministic literal-coordinate fixtures: no model estimator is called.
 legacy<-new.env();sys.source(file.path(P,'Scientific Reports Manuscript/analysis/R/core_tsr.R'),legacy);ve<-new.env();ve$legacy<-legacy;sys.source(file.path(P,'revision_scientific_reports/R/validation.R'),ve)
 fx<-matrix(c(0,0,2,0,0,2,2,2,99,99),ncol=2,byrow=TRUE);lab<-c(1,1,1,1,0);ref<-legacy$make_macro_reference(fx,lab,1);expected<-cov(fx[1:4,]);ridge<-max(mean(diag(expected)),1)*1e-8
 tests<-list();test<-function(name,ok,detail){stopifnot(ok);tests[[length(tests)+1]]<<-data.frame(test=name,status='PASS',detail=detail)}
 test('Empirical assigned subset',identical(ref[[1]]$center,c(1,1))&&max(abs(ref[[1]]$covariance-expected-diag(ridge,2)))<1e-14,'Residual extreme point excluded from group-specific mean/cov;sample covariance and exact ridge')
 small<-legacy$make_macro_reference(fx,c(1,0,0,0,0),1);test('Small-group fallback',identical(small[[1]]$center,colMeans(fx))&&max(abs(small[[1]]$covariance-diag(1+1e-8,2)))<1e-14,'Whole-data mean includes residuals;identity plus ridge')
 sg<-legacy$make_macro_reference(matrix(c(1,1,1,1,1,1),ncol=2),c(1,1,1),1);test('Singular covariance ridge',all(eigen(sg[[1]]$covariance)$values>0),'Finite singular empirical covariance becomes positive definite;not calibrated inference')
 xx<-matrix(c(3,4,3,4),ncol=2,byrow=TRUE);rr<-list(list(center=c(0,0),covariance=diag(2)),list(center=c(2,2),covariance=diag(2)))
 d<-legacy$candidate_novelty_distance(xx,1,rr);test('Squared min distance',d==5&&d==legacy$candidate_novelty_distance(xx,1,rev(rr)),'Distances25 and5,min5;component permutation invariant')
 test('No centroid-size adjustment',d==legacy$candidate_novelty_distance(xx,1:2,rr),'Duplicating same coordinates leaves squared distance unchanged')
 test('Empty references disable novelty',is.infinite(legacy$candidate_novelty_distance(xx,1,NULL)),'Residual-only Inf distance')
 mc<-list(k=2,centers=cbind(c(0,0),c(2,2)),cov=array(c(diag(2),2*diag(2)),dim=c(2,2,2)));dr<-ve$revision_reference(fx,mc,'tclust_direct');test('TCLUST array accessor',identical(dr[[2]]$center,mc$centers[,2])&&identical(dr[[2]]$covariance,mc$cov[,,2]),'Literal mock arrays only;no TCLUST fit;matching component slice,no added ridge')
 c0<-list(list(center=c(0,0),covariance=diag(2)));c1<-list(list(center=c(0,0),covariance=4*diag(2)));da<-legacy$candidate_novelty_distance(xx,1,c0);db<-legacy$candidate_novelty_distance(xx,1,c1);test('Covariance-scale eligibility flip',da>=qchisq(.995,2)&&db<qchisq(.995,2),'Same centroid25 versus6.25;cutoff10.5966:reference scale changes eligibility')
 wr(bind(tests),'geometry_unit_checks.csv','evidence');wr(expand.grid(novelty=c(.95,.975,.99,.995,.999),p=c(2,5,25))|>transform(cutoff=qchisq(novelty,p)),'chi_square_cutoffs.csv')
 wr(data.frame(check=c('Immutable inputs','Frozen completeness and seed mapping','Novelty and reference target cells','Noncontrast and Stage-I pairing','Approved R1C2 cell and paired results','Historical retained objects','Deterministic geometry fixtures','No new scientific fitting'),status='PASS',detail=c('235 SHA256 unchanged','98800 OK,282 configurations,9880 blocks','110 cells,22000 records,22 nominal strata;one duplicate scientific stratum','88 threshold+90 reference groups,200 pairs/group',paste(nrow(old),'cell rows and',nrow(oldp),'paired rows reproduced'),paste(length(paths),'historical task RDS inspected;not final Tier1 raw objects'),paste(length(tests),'literal-matrix checks'),'Aggregation/readRDS/source and literal-coordinate algebra only')),'analysis_checks.csv','evidence')
 saveRDS(z,file.path(C,'evidence/audited_scalar_records.rds'));writeLines(capture.output(sessionInfo()),file.path(C,'evidence/R_session_info.txt'));cat('R2C3_ANALYSIS_OK',nrow(cells),'cell rows;',nrow(threshold),'threshold and',nrow(refs),'reference metric contrasts\n')
}
main()
